question:
What is the output order?
console.log(1);
setTimeout(() => console.log(2));
Promise.resolve().then(() => console.log(3));
console.log(4);

What is the output order?
new Promise(resolve => { console.log(1); resolve(); console.log(2); })
  .then(() => console.log(3));
console.log(4);

What is the output order?
async function f() { console.log("a"); await null; console.log("b"); }
f();
console.log("c");

What is the output order?
Promise.resolve().then(() => { console.log(1); setTimeout(() => console.log(2)); });
setTimeout(() => console.log(3));

What is the output order?
async function a() { console.log(1); await b(); console.log(2); }
async function b() { console.log(3); }
a();
console.log(4);

What is the output order?
setTimeout(() => console.log("t"));
queueMicrotask(() => console.log("m"));
console.log("s");

What is the output order?
Promise.resolve().then(() => { console.log("a"); Promise.resolve().then(() => console.log("b")); });
setTimeout(() => console.log("c"));
